import json

# Model of the passage:
# P1: In a short period, evaluations of (contemporary) works diverge greatly.
# P2: Over time the subjective element disappears; objective "great" status
#     comes from pleasure continuing over centuries.
# Each option is encoded by what it needs and checked against P1/P2.

premises = {
    "short_term_divergence": True,           # P1 (stated as generally true)
    "objectivity_requires_long_time": True,  # P2
    "long_term_convergence": True,           # P2: subjectivity fades over time
    "claims_about_specific_past_individuals": False,  # passage gives no data on Da Vinci/Bach's lifetimes
}

options = {
    "A": {"needs": "claims_about_specific_past_individuals", "contradicts": None},
    "B": {"needs": ("short_term_divergence", "objectivity_requires_long_time"), "contradicts": None},
    "C": {"needs": None, "contradicts": "long_term_convergence"},  # big differences across eras vs. convergence
    "D": {"needs": None, "contradicts": "objectivity_requires_long_time"},  # unanimity now is not the long-time test
}

def supported(opt):
    n, c = opt["needs"], opt["contradicts"]
    if c is not None and premises[c]:
        return False
    if n is None:
        return False
    if isinstance(n, tuple):
        return all(premises[x] for x in n)
    return premises[n]

result = {k: supported(v) for k, v in options.items()}
winners = [k for k, v in result.items() if v]

if len(winners) == 1:
    print(json.dumps({
        "final_answer": winners[0],
        "evidence": {
            "support": result,
            "reason": "Contemporary works lack the long-time test, so objectively judging their value is hard."
        }
    }))
else:
    print("UNSUPPORTED")
